// src/pages/SignUpPage/SignUpPage.jsx
import React, { useState, useContext, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import styles from './SignUpPage.module.css';
import { 
  FaGoogle, 
  FaFacebook, 
  FaApple, 
  FaEye, 
  FaEyeSlash, 
  FaCheck, 
  FaTimes,
  FaInfoCircle
} from 'react-icons/fa';

export const SignUpPage = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [error, setError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [passwordStrength, setPasswordStrength] = useState(0);
  const [passwordFeedback, setPasswordFeedback] = useState({
    length: false,
    email: true,
    common: true,
    match: false,
    complex: false
  });

  const { signup } = useContext(AuthContext);
  const navigate = useNavigate();

  // Update password feedback whenever password or email changes
  useEffect(() => {
    // Check password length
    const hasLength = password.length >= 8;
    
    // Check if password contains email
    const hasEmail = email ? password.toLowerCase().includes(email.toLowerCase()) : false;
    
    // Check for common passwords
    const commonPasswords = ['password123', 'admin123', '12345678', 'qwerty123'];
    const isCommon = commonPasswords.includes(password.toLowerCase());
    
    // Check password complexity
    const hasComplex = /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/.test(password);
    
    // Check if passwords match
    const passwordsMatch = password === confirmPassword && password !== '';
    
    // Update feedback object
    setPasswordFeedback({
      length: hasLength,
      email: !hasEmail,
      common: !isCommon,
      match: passwordsMatch,
      complex: hasComplex
    });
    
    // Calculate strength (0-4)
    let strength = 0;
    if (hasLength) strength++;
    if (!hasEmail) strength++;
    if (!isCommon) strength++;
    if (hasComplex) strength++;
    
    setPasswordStrength(strength);
  }, [password, email, confirmPassword]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    
    // Validate all requirements
    if (!passwordFeedback.length || !passwordFeedback.email || 
        !passwordFeedback.common || !passwordFeedback.match || 
        !passwordFeedback.complex) {
      setError('Please ensure all password requirements are met');
      return;
    }

    setIsSubmitting(true);

    try {
      // Split the name into firstName and lastName
      const nameParts = name.trim().split(' ');
      const firstName = nameParts[0];
      const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';
      
      await signup({
        firstName,
        lastName,
        email,
        password
      });
      
      navigate('/');
    } catch (err) {
      if (err.message?.includes('already registered')) {
        setError(
          <>
            This email is already registered. <a href="/login" className={styles.loginLink}>Log in here</a>
          </>
        );
      } else {
        setError(err.message || 'An error occurred during signup. Please try again.');
      }
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSocialLogin = (provider) => {
    // Social login implementation would go here
    console.log(`Signing up with ${provider}`);
  };

  const togglePasswordVisibility = () => setShowPassword(!showPassword);
  const toggleConfirmPasswordVisibility = () => setShowConfirmPassword(!showConfirmPassword);

  return (
    <div className={styles.signUpPage}>
      <div className={styles.formCard}>
        <h1 className={styles.title}>Join Now</h1>
        <p className={styles.alreadyHaveAccount}>
          Already have an account? <a href="/login">Log In</a>
        </p>
        <p className={styles.termsText}>
          By signing up, you confirm that you are 16 years of age or older and you agree to our{' '}
          <a href="/terms">Terms of Service</a> and <a href="/privacy">Privacy Policy</a>.
        </p>

        <div className={styles.socialButtons}>
          <button onClick={() => handleSocialLogin('Google')} className={styles.googleBtn}>
            <FaGoogle /> Connect with Google
          </button>
          <button onClick={() => handleSocialLogin('Facebook')} className={styles.facebookBtn}>
            <FaFacebook /> Connect with Facebook
          </button>
          <button onClick={() => handleSocialLogin('Apple')} className={styles.appleBtn}>
            <FaApple /> Connect with Apple
          </button>
        </div>

        <div className={styles.separator}>OR</div>

        <form className={styles.signUpForm} onSubmit={handleSubmit}>
          <div className={styles.formGroup}>
            <label htmlFor="name">Full Name</label>
            <input
              id="name"
              type="text"
              placeholder="Enter your full name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
              className={styles.formInput}
            />
          </div>
          
          <div className={styles.formGroup}>
            <label htmlFor="email">Email Address</label>
            <input
              id="email"
              type="email"
              placeholder="Enter your email address"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
              className={styles.formInput}
            />
          </div>
          
          <div className={styles.formGroup}>
            <label htmlFor="password">Password</label>
            <div className={styles.passwordInputWrapper}>
              <input
                id="password"
                type={showPassword ? "text" : "password"}
                placeholder="Create a password"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                required
                className={styles.formInput}
              />
              <button 
                type="button" 
                className={styles.passwordToggle}
                onClick={togglePasswordVisibility}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? <FaEyeSlash /> : <FaEye />}
              </button>
            </div>
            
            {password && (
              <>
                <div className={styles.passwordStrengthContainer}>
                  <div className={styles.passwordStrengthLabel}>
                    Password strength: 
                    <span className={
                      passwordStrength === 0 ? styles.strengthWeak :
                      passwordStrength === 1 ? styles.strengthWeak :
                      passwordStrength === 2 ? styles.strengthMedium :
                      passwordStrength === 3 ? styles.strengthGood :
                      styles.strengthStrong
                    }>
                      {passwordStrength === 0 ? ' Very Weak' :
                       passwordStrength === 1 ? ' Weak' :
                       passwordStrength === 2 ? ' Medium' :
                       passwordStrength === 3 ? ' Good' :
                       ' Strong'}
                    </span>
                  </div>
                  <div className={styles.passwordStrengthMeter}>
                    <div 
                      className={styles.passwordStrengthIndicator} 
                      style={{
                        width: `${(passwordStrength / 4) * 100}%`,
                        backgroundColor: 
                          passwordStrength <= 1 ? 'var(--error-color)' :
                          passwordStrength === 2 ? 'var(--warning-color)' :
                          passwordStrength === 3 ? 'var(--primary-green)' :
                          'var(--success-color)'
                      }}
                    ></div>
                  </div>
                </div>
              </>
            )}
          </div>
          
          <div className={styles.formGroup}>
            <label htmlFor="confirmPassword">Confirm Password</label>
            <div className={styles.passwordInputWrapper}>
              <input
                id="confirmPassword"
                type={showConfirmPassword ? "text" : "password"}
                placeholder="Confirm your password"
                value={confirmPassword}
                onChange={(e) => setConfirmPassword(e.target.value)}
                required
                className={styles.formInput}
              />
              <button 
                type="button" 
                className={styles.passwordToggle}
                onClick={toggleConfirmPasswordVisibility}
                aria-label={showConfirmPassword ? "Hide password" : "Show password"}
              >
                {showConfirmPassword ? <FaEyeSlash /> : <FaEye />}
              </button>
            </div>
          </div>
          
          <div className={styles.passwordRequirements}>
            <h4 className={styles.requirementsTitle}>
              <FaInfoCircle /> Password Requirements
            </h4>
            <ul className={styles.requirementsList}>
              <li className={passwordFeedback.length ? styles.requirementMet : styles.requirementNotMet}>
                {passwordFeedback.length ? <FaCheck /> : <FaTimes />} 
                At least 8 characters
              </li>
              <li className={passwordFeedback.complex ? styles.requirementMet : styles.requirementNotMet}>
                {passwordFeedback.complex ? <FaCheck /> : <FaTimes />} 
                Include uppercase, lowercase, number, and special character
              </li>
              <li className={passwordFeedback.email ? styles.requirementMet : styles.requirementNotMet}>
                {passwordFeedback.email ? <FaCheck /> : <FaTimes />} 
                Doesn't contain your email
              </li>
              <li className={passwordFeedback.common ? styles.requirementMet : styles.requirementNotMet}>
                {passwordFeedback.common ? <FaCheck /> : <FaTimes />} 
                Not a common password
              </li>
              <li className={passwordFeedback.match ? styles.requirementMet : styles.requirementNotMet}>
                {passwordFeedback.match ? <FaCheck /> : <FaTimes />} 
                Passwords match
              </li>
            </ul>
          </div>
          
          {error && (
            <div className={styles.errorContainer}>
              <p className={styles.error}>{error}</p>
            </div>
          )}
          
          <button 
            type="submit" 
            className={styles.signUpButton}
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Creating Account...' : 'Create Account'}
          </button>
        </form>
      </div>
    </div>
  );
};
